import styled from 'styled-components'
import { Link } from 'react-router-dom'
import { cores } from '../../styles'

type ButtonProps = {
  fullWidth?: boolean
}

const ButtonContainer = styled.button<ButtonProps>`
  background-color: ${({ theme }) => cores.rosa};
  color: ${({ theme }) => cores.branco};
  border: none;
  padding: 8px 16px;
  font-size: 16px;
  cursor: pointer;
  transition: background-color 0.3s ease;
  width: ${({ fullWidth }) => (fullWidth ? '100%' : 'auto')};
  text-align: center;

  &:hover {
    background-color: ${cores.rosa};
  }
`

const ButtonLink = styled(Link)<ButtonProps>`
  background-color: ${cores.rosa};
  color: ${cores.branco};
  border: none;
  padding: 8px 16px;
  font-size: 16px;
  cursor: pointer;
  transition: background-color 0.3s ease;
  width: ${({ fullWidth }) => (fullWidth ? '100%' : 'auto')};
  text-align: center;
  text-decoration: none;
  display: inline-block;

  &:hover {
    background-color: ${({ theme }) => theme.colors.rosaEscuro};
  }
`

type Props = {
  type: 'button' | 'link'
  title: string
  to?: string
  onClick?: () => void
  children: string
  fullWidth?: boolean
}

const Button = ({
  type,
  title,
  to,
  onClick,
  children,
  fullWidth = false
}: Props) => {
  if (type === 'button') {
    return (
      <ButtonContainer
        type="button"
        title={title}
        onClick={onClick}
        fullWidth={fullWidth}
      >
        {children}
      </ButtonContainer>
    )
  }
  return (
    <ButtonLink to={to as string} title={title} fullWidth={fullWidth}>
      {children}
    </ButtonLink>
  )
}

export default Button
